/* AUEM bilingual chatbot — 4-tier fallback cascade, all inside our own panel.
 *
 * Tier 1  Chatbase (iframe embedded in our panel). If its iframe fails to
 *         load within the timeout →
 * Tier 2  Botpress webchat (iframe "shareable" embed in our panel; shows
 *         nothing if the bot is dead — flip enabled=false if so) →
 * Tier 3  Groq free API (allam-2-7b, SDAIA's Arabic-first model) with
 *         retrieval over this site's embedded knowledge base
 *         (window.AUEM_KB, generated by build.py). On API error →
 * Tier 4  Built-in offline keyword matcher over window.AUEM_KB —
 *         always available, bilingual, no network needed.
 *
 * The floating medallion launcher and panel chrome are always ours; hosted
 * services never inject their own bubbles. Chatbase/Botpress render as an
 * iframe that fills the panel body (their own composer is used); our input
 * row is hidden in that mode.
 *
 * Tier 3 needs a Groq key (free): https://console.groq.com/keys — injected
 * at build time (window.AUEM_GROQ_KEY, env GROQ_API_KEY). The key ships in
 * client-side JS, so keep it free-tier only and rotate it if abused.
 */
(function () {
  "use strict";

  var CHATBASE = {
    enabled: true,
    chatbotId: "RUmUM3knlclw73SgdiUZC",
    iframeUrl: "https://www.chatbase.co/chatbot-iframe/RUmUM3knlclw73SgdiUZC",
    loadTimeoutMs: 8000
  };

  var BOTPRESS = {
    // Dead trial bot responds to nothing; re-enable after recreating it on
    // the Free plan (same or new botId/clientId + fresh configUrl).
    enabled: true,
    shareUrl: "https://cdn.botpress.cloud/webchat/v3.7/shareable.html?configUrl=" +
      encodeURIComponent("https://files.bpcontent.cloud/2026/09/21/08/20260921084023-3L5AZOLU.json"),
    loadTimeoutMs: 8000
  };

  var GROQ = {
    apiKey: window.AUEM_GROQ_KEY || "",
    apiUrl: "https://api.groq.com/openai/v1/chat/completions",
    model: "allam-2-7b",
    maxTokens: 350,
    maxKbEntries: 6,
    maxKbChars: 6000,
    maxHistoryTurns: 4,
    requestTimeoutMs: 12000
  };

  var lang = (document.documentElement.lang || "ar").slice(0, 2) === "en" ? "en" : "ar";
  var KB = window.AUEM_KB || { entries: [], greeting: {}, placeholder: {}, name: {}, fallback: {}, suggestions: [] };

  function t(x) { return typeof x === "object" && x !== null ? x[lang] : x; }

  /* ---------- shared text normalization (Tiers 3 + 4) ---------- */
  var AR_DIACRITICS = /[ً-ْٰـ]/g;
  function norm(s) {
    s = (s || "").toLowerCase();
    s = s.replace(AR_DIACRITICS, "");
    s = s.replace(/[أإآٱ]/g, "ا").replace(/ة/g, "ه").replace(/[ئ]/g, "ي")
         .replace(/ى/g, "ي").replace(/ؤ/g, "و");
    s = s.replace(/[^\p{L}\p{N}\s]/gu, " ");
    return s.replace(/\s+/g, " ").trim();
  }
  function tokenSet(s) {
    return new Set(norm(s).split(" ").filter(function (w) { return w.length > 1; }));
  }

  /* ---------- offline matcher (Tier 4) ---------- */
  function score(question, entry) {
    var q = norm(question);
    var qt = tokenSet(question);
    var kw = lang === "ar" ? entry.kw_ar : entry.kw_en;
    var other = lang === "ar" ? entry.kw_en : entry.kw_ar;
    var hits = 0;
    kw.concat(other).forEach(function (k) {
      var nk = norm(k);
      if (!nk) return;
      if (q.indexOf(nk) !== -1) { hits += 2; return; }
      nk.split(" ").forEach(function (w) { if (qt.has(w)) hits += 1; });
    });
    return hits;
  }

  function kbAnswer(question) {
    var best = null, bestScore = 0;
    KB.entries.forEach(function (e) {
      var s = score(question, e);
      if (s > bestScore) { bestScore = s; best = e; }
    });
    if (best && bestScore >= 2) return t({ ar: best.a_ar, en: best.a_en });
    return null;
  }

  /* ---------- retrieval over the KB for the LLM (Tier 3) ---------- */
  function kbContext(question) {
    var scored = KB.entries.map(function (e) {
      return { entry: e, s: score(question, e) };
    }).filter(function (x) { return x.s > 0; })
      .sort(function (a, b) { return b.s - a.s; })
      .slice(0, GROQ.maxKbEntries);

    var blocks = [];
    var budget = GROQ.maxKbChars;
    scored.forEach(function (x) {
      var block = "["
        + (lang === "ar" ? x.entry.kw_ar : x.entry.kw_en).slice(0, 6).join(", ")
        + "]\n"
        + (lang === "ar" ? x.entry.a_ar : x.entry.a_en);
      if (block.length <= budget) { blocks.push(block); budget -= block.length; }
    });
    if (!blocks.length) {
      KB.entries.slice(0, 8).forEach(function (e) {
        blocks.push(lang === "ar" ? e.a_ar : e.a_en);
      });
    }
    return blocks.join("\n\n");
  }

  /* ================= panel shell (always ours) ================= */

  var launcher = document.createElement("button");
  launcher.className = "auem-chat-launcher";
  launcher.setAttribute("aria-label", t(KB.name) || "Chat");
  launcher.innerHTML =
    '<img src="../assets/img/AUEM_logo_only_trans.png" alt="" class="auem-chat-logo">' +
    '<span class="auem-chat-ping" aria-hidden="true"></span>';

  var panel = document.createElement("div");
  panel.className = "auem-chat-panel";
  panel.innerHTML =
    '<div class="auem-chat-head"><span class="dot"></span><span><strong></strong><small>' +
    (lang === "ar" ? "يرد فوراً" : "Replies instantly") +
    '</small></span><button class="auem-chat-close" aria-label="close">×</button></div>' +
    '<div class="auem-chat-body"></div>' +
    '<div class="auem-chat-input"><input type="text"><button><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 2L11 13M22 2l-7 20-4-9-9-4z"/></svg></button></div>';

  panel.querySelector(".auem-chat-head strong").textContent = t(KB.name) || "Assistant";
  var body = panel.querySelector(".auem-chat-body");
  var inputRow = panel.querySelector(".auem-chat-input");
  var input = inputRow.querySelector("input");
  input.placeholder = t(KB.placeholder) || "";

  launcher.onclick = function () { panel.classList.toggle("open"); };
  panel.querySelector(".auem-chat-close").onclick = function () { panel.classList.remove("open"); };

  document.body.appendChild(launcher);
  document.body.appendChild(panel);

  /* ---------- fallback chat UI (Tiers 3 + 4) ---------- */

  var fallbackReady = false, typingEl = null, history = [];

  function addMsg(text, who) {
    var d = document.createElement("div");
    d.className = "auem-msg " + who;
    d.textContent = text;
    body.appendChild(d);
    body.scrollTop = body.scrollHeight;
    return d;
  }
  function showTyping() {
    if (fallbackReady && !typingEl) typingEl = addMsg("…", "bot");
  }
  function hideTyping() {
    if (typingEl) { typingEl.remove(); typingEl = null; }
  }

  function ask(text) {
    if (!text.trim()) return;
    addMsg(text, "user");
    input.value = "";
    history.push({ role: "user", content: text });

    groqAnswer(text, history).then(function (reply) {
      var out = reply || kbAnswer(text) || t(KB.fallback);
      history.push({ role: "assistant", content: out });
      hideTyping();
      addMsg(out, "bot");
    });
  }

  panel.querySelector(".auem-chat-input button").onclick = function () { ask(input.value); };
  input.addEventListener("keydown", function (e) { if (e.key === "Enter") ask(input.value); });

  function buildFallbackUi() {
    if (fallbackReady) return;
    fallbackReady = true;

    var chips = document.createElement("div");
    chips.className = "auem-chips";
    KB.suggestions.forEach(function (s) {
      var b = document.createElement("button");
      b.className = "auem-chip";
      b.textContent = t(s);
      b.onclick = function () { ask(t(s)); };
      chips.appendChild(b);
    });
    body.appendChild(chips);

    addMsg(t(KB.greeting), "bot");
  }

  /* ================= Tier 3: Groq ================= */

  function groqAnswer(question, msgs) {
    if (!GROQ.apiKey) return Promise.resolve(null);

    var sys = lang === "ar"
      ? "أنت مساعد الاتحاد العربي للطاقة والمعادن (AUEM). أجب بالعربية الفصحى بأسلوب ودود وموجز، اعتماداً حصراً على المعلومات المزودة؛ إن لم تكفِ فاعتذر بلباقة ووجّه الزائر إلى صفحة «اتصل بنا»."
      : "You are the assistant of the Arab Union for Energy & Minerals (AUEM). Answer briefly in the user's language, based ONLY on the provided knowledge; if it is insufficient, politely say so and point the visitor to the Contact page.";

    var messages = [{ role: "system", content: sys }];
    (msgs || []).slice(-GROQ.maxHistoryTurns).forEach(function (m) { messages.push(m); });
    messages.push({
      role: "user",
      content: question + "\n\n---\n" +
        (lang === "ar" ? "المعرفة المتاحة:" : "Available knowledge:") + "\n" +
        kbContext(question)
    });

    var ctrl = new AbortController();
    var timer = setTimeout(function () { ctrl.abort(); }, GROQ.requestTimeoutMs);
    showTyping();

    return fetch(GROQ.apiUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": "Bearer " + GROQ.apiKey
      },
      body: JSON.stringify({
        model: GROQ.model,
        temperature: 0.3,
        max_tokens: GROQ.maxTokens,
        messages: messages
      }),
      signal: ctrl.signal
    }).then(function (res) {
      clearTimeout(timer);
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    }).then(function (data) {
      var content = data && data.choices && data.choices[0] &&
        data.choices[0].message && data.choices[0].message.content;
      if (!content) throw new Error("empty reply");
      return content;
    }).catch(function (err) {
      clearTimeout(timer);
      hideTyping();
      console.warn("[AUEM chat] Groq tier failed:", err);
      return null; // cascade to Tier 4
    });
  }

  /* ================= embedded mode (Tiers 1 + 2) ================= */

  function testEmbed(url, timeoutMs) {
    return new Promise(function (resolve) {
      var frame = document.createElement("iframe");
      frame.className = "auem-chat-embed";
      frame.setAttribute("title", t(KB.name) || "Chat");
      frame.setAttribute("allow", "microphone");
      var settled = false;

      var timer = setTimeout(function () {
        if (settled) return;
        settled = true;
        frame.remove(); // cascade to the next tier
        resolve({ ok: false, frame: null });
      }, timeoutMs);

      frame.onload = function () {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve({ ok: true, frame: frame });
      };
      frame.onerror = function () {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        frame.remove();
        resolve({ ok: false, frame: null });
      };

      frame.src = url;
      body.appendChild(frame); // loads even while the panel is closed
    });
  }

  function adoptEmbed(frame) {
    // hide fallback state (if any) and show the loaded hosted chat
    Array.prototype.forEach.call(body.children, function (c) {
      if (c !== frame) c.remove();
    });
    typingEl = null;
    inputRow.style.display = "none";
    panel.classList.add("embedded");
    frame.style.display = "block";
  }

  function useFallback() {
    if (fallbackReady) return;
    // drop any half-loaded embed iframes
    Array.prototype.forEach.call(body.querySelectorAll(".auem-chat-embed"), function (f) { f.remove(); });
    inputRow.style.display = "";
    buildFallbackUi();
  }

  /* ================= tier resolution ================= */

  var tier = "pending";
  Object.defineProperty(window, "AUEM_CHAT_TIER", { get: function () { return tier; } });
  function setTier(v) { tier = v; document.body.setAttribute("data-ai-tier", v); }

  function nextFailsafe() {
    // Hosted tiers exhausted → Groq (+ offline matcher) with our own UI.
    setTier("groq-or-builtin");
    useFallback();
  }

  function tryBotpress() {
    if (!BOTPRESS.enabled) { nextFailsafe(); return; }
    testEmbed(BOTPRESS.shareUrl, BOTPRESS.loadTimeoutMs).then(function (r) {
      if (r.ok) { setTier("botpress"); adoptEmbed(r.frame); }
      else { nextFailsafe(); }
    });
  }

  function tryChatbase() {
    if (!CHATBASE.enabled) { tryBotpress(); return; }
    testEmbed(CHATBASE.iframeUrl, CHATBASE.loadTimeoutMs).then(function (r) {
      if (r.ok) { setTier("chatbase"); adoptEmbed(r.frame); }
      else { tryBotpress(); }
    });
  }

  tryChatbase();
})();
